/// <summary>
/// This class is called METPickDirectorDataEntitity has done the import.
/// </summary>
class METPickDirectorDataController
{
    SalesTable salesTablePick;
    METPickDirectorData pickDirectorData;
    Map soLineWithQtyPick;

}

Method.Source:
/// <summary>
/// Process the sales orders which are macthing with the METPickDirectorData.
/// </summary>
public void processSOForPickDirectorData()
{
    #OCCRetryCount
    System.Exception netExcepn;

    try
    {
        while select SalesId from salesTablePick group by SalesId
            exists join pickDirectorData
            where salesTablePick.SalesId == pickDirectorData.SalesId
            && salesTablePick.SalesStatus == SalesStatus::Backorder
        {
            soLineWithQtyPick = this.deriveSoLinesAndQtyPicked();
            ttsbegin;
            // Reservation
            this.reserveSOLineQty();

            // Generate and post picking list
            WMSPickingRouteID pickingRouteID = this.createSalesPickingListSingleLine();

            // Register picking list
            if (pickingRouteID)
            {
                this.registerPickingList(pickingRouteID);
            }
            ttscommit;
        }
    }
    catch (Exception::CLRError)
    {
        netExcepn = CLRInterop::getLastException();
        throw error(netExcepn.ToString());
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch
    {
        exceptionTextFallThrough();
    }
    finally
    {
        delete_from pickDirectorData;
    }
}

/// <summary>
/// Reserves the sales order line with the quantity picked.
/// </summary>
public void reserveSOLineQty()
{
    MapEnumerator mapEnumerator = soLineWithQtyPick.getEnumerator();

    while (mapEnumerator.moveNext())
    {
        if (mapEnumerator.currentValue() > 0)
        {
            SalesLine salesLine = mapEnumerator.currentKey();
            InventMovement movement = InventMovement::construct(salesLine);
            InventUpd_Reservation reservation = InventUpd_Reservation::newMovement(movement, -mapEnumerator.currentValue(), true);
            reservation.updateNow();
        }
    }
}

/// <summary>
/// Generated and posts the picking list for the sales order line with the quantity picked.
/// </summary>
/// <returns>WMSPickingRouteID</returns>
public WMSPickingRouteID createSalesPickingListSingleLine()
{
    salesTable salesTable = salesTable::find(salesTablePick.SalesId);
    SalesFormLetter salesFormLetter = SalesFormLetter::construct(DocumentStatus::PickingList);
    salesFormLetter.salesTable(salesTable);
    salesFormLetter.initParmSalesTable(salesFormLetter.salesTable());
    salesFormLetter.transDate(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
    salesFormLetter.specQty(SalesUpdate::All);
    salesFormLetter.printFormLetter(salesFormLetter.printFormLetter());

    salesFormLetter.createParmUpdateFromParmUpdateRecord(
    SalesFormletterParmData::initSalesParmUpdateFormletter(
        salesFormLetter.documentStatus(),
        salesFormLetter.pack()));

    salesFormLetter.initParameters(
    salesFormLetter.salesParmUpdate(),
    Printout::Current);

    salesFormLetter.initLinesQuery();

    SalesParmLine salesParmLine;
    Map inventTransMap = new Map(Types::String, Types::Real);
    MapEnumerator mapEnumerator = soLineWithQtyPick.getEnumerator();

    while (mapEnumerator.moveNext())
    {
        if (mapEnumerator.currentValue() > 0)
        {
            SalesLine salesLine = mapEnumerator.currentKey();
            inventTransMap.insert(salesLine.InventTransId, mapEnumerator.currentValue());
        }
    }

    // Delete unwanted records in SalesParmLine
    while select forupdate salesParmLine
        where salesParmLine.ParmId == salesFormLetter.parmId()
    {
        if (!inventTransMap.exists(salesParmLine.InventTransId))
        {
            salesParmLine.delete();
        }
        else
        {
            salesParmLine.DeliverNow = inventTransMap.lookup(salesParmLine.InventTransId);
            salesParmLine.setQty(DocumentStatus::PickingList, false);
            salesParmLine.update();
        }
    }

    salesFormLetter.run();

    WMSPickingRoute wmsPickingRoute;

    select firstonly pickingRouteID from wmsPickingRoute
            where wmsPickingRoute.parmid == salesFormLetter.parmId();

    return wmsPickingRoute.pickingRouteID;
}

/// <summary>
/// Registers the picking list for the selected sales line.
/// </summary>
/// <param name = "_pickingRouteID">_pickingRouteID</param>
public void registerPickingList(WMSPickingRouteID _pickingRouteID)
{
    Map inventTransMap = new Map(Types::String, Types::Real);
    InventTransId inventTransId;
    Qty pickQty;
    List list = new List(Types::String);
    WmsOrderTrans wmsOrderTrans;
    WmsOrderTrans wmsOrderTransNew;

    list.addEnd(_pickingRouteID);

    int incr;
    MapEnumerator mapEnumerator = soLineWithQtyPick.getEnumerator();

    while (mapEnumerator.moveNext())
    {
        if (mapEnumerator.currentValue() > 0)
        {
            incr++;
            SalesLine salesLine = mapEnumerator.currentKey();
            // Build map containing the lot-ids and quantity to pick
            inventTransMap.insert(salesLine.InventTransId, mapEnumerator.currentValue());
        }
    }


    MapEnumerator me = inventTransMap.getEnumerator();

    while (me.moveNext())
    {
        inventTransId = me.currentKey();
        pickQty = me.currentValue();

        ttsBegin;
        select firstonly forupdate wmsOrderTrans
            where wmsOrderTrans.RouteId == _pickingRouteID &&
            wmsOrderTrans.inventTransId == inventTransId &&
            wmsOrderTrans.FullPallet == NoYes::No &&
            (wmsOrderTrans.ExpeditionStatus == WMSExpeditionStatus::Registered ||
            wmsOrderTrans.ExpeditionStatus == WMSExpeditionStatus::Activated  ||
            wmsOrderTrans.ExpeditionStatus == WMSExpeditionStatus::Started);

        if (wmsOrderTrans.Qty > pickQty)
        {
            // Split line
            wmsOrderTransNew = wmsOrderTrans.split(pickQty);
        }
        ttsCommit;

        if (wmsOrderTrans.Qty > pickQty)
        {
            ttsBegin;
            // Cancel remaining line
            wmsOrderTrans.cancel();
            ttsCommit;
        }
    }

    WMSPickingRoute::finishMulti(list.pack());
}

/// <summary>
/// Derives the sales lines and qty picked into a map.
/// </summary>
public Map deriveSoLinesAndQtyPicked()
{
    METPickDirectorData metPickDirectorData;
    SalesLine salesLine;

    soLineWithQtyPick = new Map(Types::Record, Types::Real);

    while select forupdate salesLine
        where salesLine.SalesStatus == SalesStatus::Backorder
        && salesLine.SalesId == salesTablePick.SalesId
    join QtyPicked from metPickDirectorData
        where salesLine.SalesId == metPickDirectorData.SalesId
        && salesLine.LineNum == metPickDirectorData.LineNum
        && salesLine.ItemId == metPickDirectorData.ItemId

    {
        soLineWithQtyPick.insert(salesLine, metPickDirectorData.QtyPicked);
    }

    return soLineWithQtyPick;
}
